issue.body:
### What happened?

`_format_TracebackException` assumes the `TracebackException.format` result is a newline-terminated buffer and truncates it in place, so a crafted override that returns an empty sequence makes the code treat a one-byte allocation as if it held a trailing `\n`, writing past the buffer and turning the mistaken type expectation into a heap buffer overflow.

**Proof of Concept:**

```python
import traceback
import _interpreters

orig_format = traceback.TracebackException.format

def empty_format(self):
    return []

traceback.TracebackException.format = empty_format

try:
    raise ValueError("boom")
except Exception as exc:
    _interpreters.capture_exception(exc)
finally:
    traceback.TracebackException.format = orig_format
```

**Vulnerable Code Snippet:**

<details>

<summary>Click to expand</summary>

```c
/* Buggy Re-entrant Path */
static PyObject *
_interpreters_capture_exception_impl(PyObject *module, PyObject *exc_arg)
{
    PyObject *exc = exc_arg;
    /* ... */
    _PyXI_excinfo *info = _PyXI_NewExcInfo(exc);
    if (info == NULL) {
        goto finally;
    }
    /* ... */
    PyObject *formatted = _PyXI_FormatExcInfo(info);
    if (formatted == NULL) {
        Py_CLEAR(captured);
        goto finally;
    }
    /* ... */
    return captured;
}

_PyXI_excinfo *
_PyXI_NewExcInfo(PyObject *exc)
{
    _PyXI_excinfo *info = PyMem_RawCalloc(1, sizeof(_PyXI_excinfo));
    /* ... */
    if (PyExceptionInstance_Check(exc) || PyExceptionClass_Check(exc)) {
        failure = _PyXI_excinfo_InitFromException(info, exc);
    }
    /* ... */
    return info;
}

static const char *
_PyXI_excinfo_InitFromException(_PyXI_excinfo *info, PyObject *exc)
{
    /* ... */
    info->errdisplay = _format_TracebackException(tbexc);
    /* ... */
    return NULL;
}

static const char *
_format_TracebackException(PyObject *tbexc)
{
    PyObject *lines = PyObject_CallMethod(tbexc, "format", NULL);  /* Reentrant call site */
    if (lines == NULL) {
        return NULL;
    }
    assert(_Py_EMPTY_STR != NULL);
    PyObject *formatted_obj = PyUnicode_Join(_Py_EMPTY_STR, lines);
    Py_DECREF(lines);
    if (formatted_obj == NULL) {
        return NULL;
    }

    Py_ssize_t size = -1;
    const char *formatted = _copy_string_obj_raw(formatted_obj, &size);  /* crashing pointer derived */
    Py_DECREF(formatted_obj);
    // Assume the formatted ends with \n while we can return an empty object
    // We remove trailing the newline added by TracebackException.format().
    assert(formatted[size-1] == '\n');
    ((char *)formatted)[size-1] = '\0';  /* Crash site */
    return formatted;
}

/* Clobbering Path */
static const char *
_copy_string_obj_raw(PyObject *strobj, Py_ssize_t *p_size)
{
    Py_ssize_t size = -1;
    const char *str = PyUnicode_AsUTF8AndSize(strobj, &size);
    if (str == NULL) {
        return NULL;
    }
    /* ... */
    char *copied = PyMem_RawMalloc(size+1);
    if (copied == NULL) {
        PyErr_NoMemory();
        return NULL;
    }
    strcpy(copied, str);
    if (p_size != NULL) {
        *p_size = size;  /* state mutate site */
    }
    return copied;
}
```
</details>

